import React, { memo, useMemo, useState, useRef } from 'react';
import { useSelector } from 'react-redux';

// packages
import styled, { createGlobalStyle } from 'styled-components';

// components
import { Form, Select, message } from 'antd';
import authApi from 'services/authApi';
import { departmentOptions } from 'components/common/UpdateRoleModal';
import { InfoBox } from 'components/features/onboard/SignupSecondaryLayout';
import {
  SectionHeader,
  SelectWrapper,
  ChevronDown,
} from 'components/features/onboard/FlowScreens/common';
import ReCAPTCHA from 'react-google-recaptcha';

// utils
import { handleErrorMessage } from 'Utils/helpers/commonUtils';
import { rollbar } from 'components/common/rollbar';
import redirectUrlHandler from 'Utils/helpers/redirectUrlHandler';
import axios from 'axios';

import TextInput from '../../TextInput';
import FlowLayout from '../../FlowLayout';
import FlowNavButtons from '../../FlowNavButtons';
import PasswordInput from '../../SetupPassword/PasswordInput';
import { ErrorText } from '../../SetupPassword';
import { focusInput } from '../OrganizationApps';
import { useFormData } from '../../context/signupFlowData.context';
import { PrivacyPolicy } from '../common'

export const GlobalStyles = createGlobalStyle`
  .ant-select-dropdown {
    border-radius: 8px;
    box-shadow: none;
    border: 1px solid #E8E8EB;
    padding: 0;
    .ant-select-item {
      font-family: Roboto;
      font-weight: 400;
      font-style: Regular;
      font-size: 14px;
      line-height: 132%;
      letter-spacing: 1%;
      color: #161E35;
      padding: 16px;
      &:hover {
        background-color: #EFF5FF;
      }
      &.ant-select-item-option-selected {
        color: #5D97FF;
      }
    }
  }
`;

const FormStyled = styled(Form)`
  width: 100%;
`;

const HorizontalWrapper = styled.div`
  display: flex;
  flex-direction: row;
  gap: 24px;
`;

const SideWrapper = styled.div`
  flex: 1;
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  width: 100%;
  margin-bottom: 8px;
`;

export const selectStyles = {
  // background: 'white',
  border: 'none',
  width: '100%',
  textAlign: 'left',
};

const TeamInvite = (props) => {
  const [form] = Form.useForm();
    const {
    token,
    isEmailInvitation,
    invitation_token: invitationToken,
    secret,
    redirectUrl,
    isValidRedirectUrl,
    teamData,
    userInfo,
  } = props;
  const { formData } = useFormData();
  const { currentOrgReducer } = useSelector((state) => state);
  const [loading, setLoading] = useState(false);
  const [showPasswordRequirements, setShowPasswordRequirements] = useState(false);
  const [passwordValid, setIsPasswordValid] = useState(false);
  const [passwordValue, setPasswordValue] = useState('');
  const [passwordErrorMessage, setPasswordErrorMessage] = useState(null);
  const [ssoErrorMessage, setSSOErrorMessage] = useState(null);
  const recaptchaRef = useRef();
  const isSSO = currentOrgReducer?.planFeature?.SAMLSingleSignOn === 1

  const onFinish = async (values) => {
    if (isSSO) {
      await axios({
        method: 'post',
        url: `${process.env.API_URL}/sso/detail`,
        data: { email: userInfo?.acceptor?.email },
        withCredentials: true,
      })
        .then((response) => {
          const responseUrl = response.data.data.redirectUrl;
          if (response.status === 200)
            redirectUrlHandler(`${responseUrl}?redirect=${btoa(redirectUrl)}`);
        })
        .catch((err) => {
          const errMsg = err.response.data.error.error;
          rollbar.error('SSO signin error', err);
          setSSOErrorMessage(errMsg);
        });
      
      return;
    }
    
    let postData = {};
    setLoading(true);

    const captchaToken = await recaptchaRef.current?.executeAsync()

    postData = {
      name: values.name,
      companyName: userInfo?.organization?.name,
      email: userInfo?.acceptor?.email,
      password: values.password,
      department: values.flow_department,
      phone: null,
      captchaToken,
      ...(isEmailInvitation && { duplicateSignupKey: invitationToken }),
      ...(token && { token }),
      ...(secret && { secret }),
    };

    await axios({
      method: 'post',
      url: `${process.env.AUTH_API_URL}/user/team-signup`,
      data: postData,
      withCredentials: true,
    })
      .then(async (response) => {
        window.dataLayer = window.dataLayer || [];

        if (token?.length) {
          try {
            await authApi.teamInvitationAccept(token);
          } catch (error) {
            rollbar.error('Team signup error', error);
          }
        }

        window.dataLayer.push({
          event: 'Team Member Sign Up',
        });

        window.dataLayer.push({
          event: 'formSubmissionSuccess',
          formId: 'registration-form',
          signupEmail: userInfo?.acceptor?.email,
          userId: response?.data?.data?.customer?.id,
          orgID: response?.data?.data?.organization?.id,
        });

        const isTeamInvitationUrl = redirectUrl?.includes('/team/invitation/');
        if (redirectUrl && isValidRedirectUrl && !isTeamInvitationUrl) {
          return redirectUrlHandler(redirectUrl);
        }
        if (teamData || invitationToken) {
          window.location.href = `${process.env.REDIRECT_URL}/dashboard`;
        }

        return null;
      })
      .catch((error) => {
        if (error.response) {
          rollbar.error(
            `TEAM SIGN UP ERROR with error response: ${JSON.stringify(
              error.response.data,
              null,
              2
            )}`
          );
          handleErrorMessage(error.response);
        } else {
          rollbar.error('TEAM SIGN UP ERROR:', error);
          message.error('Something went wrong. Please try again later.');
        }
      })
      .finally(() => setLoading(false));
  };

  const SelectOptions = useMemo(() => departmentOptions, []);

  const handleInputChange = (e) => {
    setShowPasswordRequirements(true);
    setPasswordValue(e.target.value);
  };

  return (
    <>
      <ReCAPTCHA
        ref={recaptchaRef}
        size="invisible"
        sitekey={process.env.SITE_KEY}
      />
      <GlobalStyles />
      <FlowLayout
        title="Account setup"
        subTitle={ isSSO ? 'To get started, log in with your company’s SSO.' : 'Complete your profile to get started' }
        hideLogos
      >
        <FormStyled
          form={form}
          onFinish={onFinish}
          validateTrigger={['onSubmit']}
          noValidate
          // eslint-disable-next-line no-shadow
          onValuesChange={(props) => {
            const key = Object.keys(props)?.[0]
            switch(key) {
              case 'privacyPolicy':
                form.setFields([{
                  name: 'privacyPolicy',
                  errors: []
                }])
                break
              case 'flow_department':
                form.setFields([{
                  name: 'flow_department',
                  errors: []
                }])
                break
              case 'name':
                form.setFields([{
                  name: 'name',
                  errors: []
                }])
                break
              case 'password':
                setPasswordErrorMessage(null)
                break
              default:
                return null
            }
          }}
          initialValues={{
            name: formData?.fullName,
            flow_department: formData?.department || undefined,
            phone: formData?.phone,
          }}
        >
          <InfoBox
            text={
              <>
                You&apos;ve been invited to join &apos;{userInfo?.organization?.name}
                &apos; on UXCam with the email: {userInfo?.acceptor?.email}.
              </>
            }
          />
          {!isSSO && (
            <>
              <HorizontalWrapper>
                <SideWrapper>
                  <SectionHeader>Enter your name</SectionHeader>
                  <TextInput
                    placeholder="Your full name"
                    name="name"
                    rules={[
                      {
                        required: true,
                        message: 'Your name is required',
                      },
                    ]}
                  />
                </SideWrapper>
                <SideWrapper>
                  <SelectWrapper>
                    <SectionHeader>Select your department</SectionHeader>
                    <Form.Item
                      name="flow_department"
                      rules={[
                        {
                          validator: (_, depValue) => {
                            if (!depValue?.length) {
                              return Promise.reject(new Error('Your department is required'))
                            }
                            return Promise.resolve()
                          }
                        }
                      ]}
                    >
                      <Select
                        placeholder="Select a department"
                        style={selectStyles}
                        options={SelectOptions}
                        suffixIcon={<ChevronDown />}
                      />
                    </Form.Item>
                  </SelectWrapper>
                </SideWrapper>
              </HorizontalWrapper>
              <Wrapper>
                <SectionHeader>Create a password</SectionHeader>
                <Form.Item
                  className='privacypolicy'
                  name="privacyPolicy"
                  validateTrigger={['onSubmit']}
                  hidden
                  rules={[
                    {
                      validator: () => {
                        if (!passwordValue?.length) {
                          setPasswordErrorMessage('Password is required');
                          setShowPasswordRequirements(false)
                          return Promise.reject()
                        }

                        if (!passwordValid) {
                          setPasswordErrorMessage('Your password needs to meet all the conditions below');
                          setShowPasswordRequirements(true)
                          return Promise.reject()
                        }
                        return Promise.resolve()
                      }
                    }
                  ]} />
                <PasswordInput
                  showPasswordRequirements={showPasswordRequirements}
                  value={passwordValue}
                  error={passwordErrorMessage}
                  onChange={handleInputChange}
                  setIsPasswordValid={setIsPasswordValid}
                />
              </Wrapper>
              <Form.Item
                className='privacypolicy'
                name="privacyPolicy"
                valuePropName='checked'
                validateTrigger={['onSubmit']}
                rules={[
                  {
                    validator: (_, privacyValue) => {
                      if (!privacyValue) {
                        focusInput('privacyPolicy')
                        return Promise.reject(new Error('Please accept the terms and conditions and data processing agreement'))
                      }
                      return Promise.resolve()
                    }
                  }
                ]}>
                <PrivacyPolicy loading={loading} />
              </Form.Item>
            </>
          )}
          {ssoErrorMessage && <ErrorText>{ssoErrorMessage}</ErrorText>}
          <FlowNavButtons
            loading={loading}
            primaryText={ isSSO ? 'Continue using SSO' : 'Finish setup' }
          />
        </FormStyled>
      </FlowLayout>
    </>
  );
};

export default memo(TeamInvite);