/* eslint-disable prefer-const */
import React, { useEffect, useRef } from 'react'
import styled from 'styled-components'
import { Form, message } from 'antd'
import { emailRegex } from 'Utils/helpers/commonUtils'
import hubspot from 'Utils/helpers/hubspot';
import { rollbar } from 'components/common/rollbar';
import { setAuthValuesByStep, setKeyByValue } from 'redux/actions/auth'
import { trackPageViews } from 'redux/actions/trackingReport'
import { useDispatch } from 'react-redux'
import blockedEmailList from 'components/features/onboard/blockedEmailList.json'
import { FlowWrapper, SectionHeader } from 'components/features/onboard/FlowScreens/common'
import blockedExt from 'components/features/onboard/blockedExt.json'
import ReCAPTCHA from 'react-google-recaptcha'
import { isEmail } from 'react-multi-email'
import { PrivacyPolicy } from '../common'
import FlowLayout from '../../FlowLayout'
import TextInput from '../../TextInput'
import FlowNavButtons from '../../FlowNavButtons'
import { usePageState } from '../../context/signupPages.context'
import AlreadyHaveAccount from '../../Signup/AlreadyHaveAccount';
import { useFormData } from '../../context/signupFlowData.context'
import { focusInput } from '../OrganizationApps'
import JoinExistingOrganization from '../../Signup/JoinExistingOrganization';

declare global {
	interface Window {
		dataLayer: unknown[];
	}
}

const AlreadyHaveAccountWrapper = styled.div`
	margin-top: 16px;
`

interface FormData {
	email: string;
	organizationName: string;
	mobileApps: string;
	webDomains: string;
}

interface IProps {
	invitationData: {
		email: string
	}
}

let controller: AbortController | null = null
const API_ID = process.env.FLOW_ADD_APP_ID;

const EmailFlow = ({ invitationData }: IProps) => {
	const [loading, setLoading] = React.useState(false)
	const [ctaQueryString, setCtaQueryString] = React.useState('')
	const recaptchaRef = useRef<ReCAPTCHA | null>(null)

	const [form] = Form.useForm<FormData>();
	const { setPage } = usePageState();
	const { formData, setValues } = useFormData();
	const dispatch = useDispatch()

	const shouldFocusOnFirstInput = useRef(true)
	useEffect(() => {
		if (shouldFocusOnFirstInput?.current) {
			focusInput('email')
			shouldFocusOnFirstInput.current = false
		}
	}, [])

	const onFinish = React.useCallback(async (values: FormData) => {
		setLoading(true)
		if (controller) {
			controller.abort()
		}

		const { email } = values
		try {
			if (!isEmail(email)) {
				return
			}

			const valAfter = email?.split('@').pop()?.trim()
			const valAfterDot = valAfter?.split('.').pop()?.trim() || ''
			const containsEmailFlag = valAfter && (blockedEmailList.includes(valAfter) || blockedExt.includes(valAfterDot))
			if ((!invitationData && containsEmailFlag)) {
				rollbar.info(`${email} [Invalid company email]`)
				form.setFields([{
					name: 'email',
					errors: ['Please enter a valid work email']
				}])
				setLoading(false)
				return
			}

			if (!invitationData && !containsEmailFlag) {
				const captchaToken = await recaptchaRef.current?.executeAsync()
				const response = await fetch(`${process.env.AUTH_API_URL}/user/check-email`, {
					signal: controller?.signal,
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
					},
					body: JSON.stringify({
						email,
						captchaToken,
					}),
					credentials: 'include',
				})
					.then(async (res) => {
						return {
							status: res.status,
							data: await res.json() as unknown as {error: {message: string}}
						}
					})
					.catch((err) => {
						message.info('Something went wrong. Please try again later.', 2.5)
						setLoading(false)
						if (err && err.response) {
							const [errorMessage] = err.response.data['error']['email'] || err.response.data['error']['message']
							form.setFields([{
								name: 'email',
								errors: [errorMessage]
							}])
						}
					});

				if (response?.status === 302) {
					message.info('You are already logged in to another account, please refresh your page', 2.5)
					setLoading(false)
					return
				}
				if (response?.status !== 200) {
					form.setFields([{
						name: 'email',
						errors: [response?.data?.error?.message || 'Please enter a valid work email']
					}])
					setLoading(false)
					return
				}
			}
		} catch (error) {
			message.error('Something went wrong. Please try again later.', 2.5)
			const fromData = form.getFieldsValue()
			rollbar.error(error as Error, fromData)
			setLoading(false)
			return
		}

		dispatch(setAuthValuesByStep({ email }, 0))
		dispatch(setKeyByValue('onBoardVisible', true))
		dispatch(setKeyByValue('isActivation', false))
		dispatch(setKeyByValue('queryString', ctaQueryString))
		
		await hubspot.submitForm({
			email,
		}, API_ID)
			.catch((err) => rollbar.error(err))
		const captchaToken = await recaptchaRef.current?.executeAsync()
		dispatch(trackPageViews(null, {
			eventName: 'wa_signup_email_submitted',
			eventProperty: {
				email,
			},
		}, captchaToken ))

		setLoading(false)
		if (setPage) {
			setPage((currentPage) => (currentPage || 0) + 1);
		}
		 if ( setValues ) {
			setValues({
			  email,
			})
		 }
	}, [setPage, ctaQueryString, setValues, dispatch, form, invitationData, recaptchaRef])

	useEffect(() => {
		if (typeof window === 'undefined') return

		const queryString = window.location.search
		const searchText = queryString?.substring(1)
		if (searchText?.includes('cta')) {
			setCtaQueryString(searchText)
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [dispatch, formData?.email, invitationData?.email])

	return (
		<FlowLayout
			title={invitationData ? (
				"You've been invited to join your team's organization."
			) : (
				"Sign up for free today."
			)}
			subTitle={invitationData ? (
				'Create your account to get started.'
			) : (
				<>
					Access all features during your 14-day free trial.
					<br />
					No credit card required.
				</>
			)
			}
		>
			<ReCAPTCHA
				ref={recaptchaRef}
				size="invisible"
				sitekey={process.env.SITE_KEY || ''}
			/>
			<FlowWrapper>
				<Form
					form={form}
					onFinish={onFinish}
					layout="vertical"
					autoComplete="off"
					noValidate
					initialValues={{
						email: invitationData?.email || formData?.email,
					}}
				>
					<div>
						<SectionHeader>
							Enter work email
						</SectionHeader>
						<TextInput
							ariaLabel='email input'
							placeholder='john@example.com'
							disabled={loading || !!invitationData?.email}
							validateTrigger={['onSubmit']}
							onInputChange={() => {
								form.setFields([{
									name: 'email',
									errors: []
								}])
							}}
							name="email" 
							rules={
								[
									{
										validator: (_: unknown, value: string) => {
											if (!value?.length) {
												focusInput('email')
												return Promise.reject(new Error('A valid work email is required'))
											}
											if (value.length < 3) {
												focusInput('email')
												return Promise.reject(new Error('Email should contain at least 3 characters.'))
											}
											if (value.length > 254) {
												focusInput('email')
												return Promise.reject(new Error('Email should contain at most 254 characters.'))
											}
											if (!emailRegex.test(value)) {
												focusInput('email')
												return Promise.reject(new Error("Email field only accepts the following characters: alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), and spaces."))
											}
											return Promise.resolve()
										}
									}
								]}
						/>
						<Form.Item
							className='privacypolicy'
							name="privacyPolicy"
							valuePropName='checked'
							validateTrigger={['onSubmit']}
							rules={[
								{
									validator: (_, value) => {
										if (!value) {
											focusInput('privacyPolicy')
											return Promise.reject(new Error('Please accept the terms and conditions and data processing agreement'))
										}
										return Promise.resolve()
									}
								}
							]}>
							<PrivacyPolicy
								loading={loading}
								onChange={() => {
									form.setFields([{
										name: 'privacyPolicy',
										errors: []
									}])
								}}
							/>
						</Form.Item>
					</div>
					<FlowNavButtons
						primaryText="Create an account"
						loading={loading}
					/>
				</Form>
			</FlowWrapper>
			<AlreadyHaveAccountWrapper>
				<AlreadyHaveAccount />
			</AlreadyHaveAccountWrapper>
			<AlreadyHaveAccountWrapper>
				<JoinExistingOrganization />
			</AlreadyHaveAccountWrapper>
		</FlowLayout>
	)
}

export default EmailFlow