import React, { memo, useEffect } from 'react';

// packages
import styled from 'styled-components';
import { isEmpty } from 'lodash';
import { useDispatch } from 'react-redux';

// components
import { Button } from 'antd';
import { CloseIcon } from 'components/svg_files';

// constants
import { showIntercom } from 'Utils/constants/index'
import EmailIcon from 'public/static/signup/flow-icons/check-email.svg'

// utils
import { trackPageViews } from 'redux/actions/trackingReport';
import ReCAPTCHA from 'react-google-recaptcha';

import useCommonModal from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/components/CommonModal';
import FlowLayout from '../../FlowLayout';
import { useFormData } from '../../context/signupFlowData.context';

const IconWrapper = styled.div`
  height: 116px;
  width: 116px;
  border-radius: 50%;
  background-color: #EBEBEC;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto;
  margin-bottom: 24px;
`

// styles
const buttonStyles = {
  borderRadius: 4,
  fontSize: 18,
  padding: '20px 24px',
  display: 'flex',
  alignItems: 'center',
  fontWeight: 'lighter' as const,
};

const ButtonWrapper = styled.div`
  margin-top: -16px;
  .ant-btn.ant-btn-link {
    padding: 0 !important;
    border: 0 !important;
    color: #5D97FF !important;
    font-size: 14px !important;
    line-height: 22px !important;

    &:hover {
      color: #161E35 !important;
    }
  }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  overflow-y: auto;
`

const ModalWrapper = styled.div`
  > button {
    position: absolute;
    top: 16px;
    right: 16px;
    cursor: pointer;
    z-index: 10;
    border: none;
    background: transparent;
    box-shadow: none;
  }
`

interface AuthData {
  _formData?: {
    step_1_data?: {
      email: string;
    };
  };
}

interface IProps {
  _auth: AuthData;
}

const ThankYou = (props: IProps) => {
  const dispatch = useDispatch();
  const recaptchaRef = React.useRef<ReCAPTCHA>(null)
  const handleCta = () => {
    showIntercom();
  };
  
  const { _auth: auth } = props;
  const signupData = !isEmpty(auth) ? auth['_formData'] : {};
  const email = encodeURIComponent(signupData?.step_1_data?.email || '');

  const { formData } = useFormData()

  const fullName = formData?.fullName

  const nameParts = fullName?.split(' ') || [];
  const firstname = encodeURIComponent(nameParts[0] || '');
  const lastname = encodeURIComponent(nameParts.slice(1).join(' '));

  const { openModal, setOpenModal, CommonModal } = useCommonModal()

  useEffect(() => {
    const handleTrackPageViews = async () => {
      const token = await recaptchaRef.current?.executeAsync()
      dispatch(trackPageViews(null, {
        eventName: 'wa_screenvisit_signup_verification_sent',
        eventProperty: {
          email: signupData?.step_1_data?.email || formData?.email || '',
          orgName: formData?.organizationName || '',
        },
      }, token));
    }
    handleTrackPageViews()
  }, [dispatch, signupData?.step_1_data?.email, formData?.email, formData?.organizationName]);

  return (
    <Wrapper>
      <ReCAPTCHA
        ref={recaptchaRef}
        size="invisible"
        sitekey={process.env.SITE_KEY || ''}
      />
      <FlowLayout
        title="Check your email to verify your account."
        subTitle="We've sent you an email with a link to activate your account."
        hideLogos
        preElement={
          <IconWrapper>
            <EmailIcon />
          </IconWrapper>
        }
      >
        <ButtonWrapper>
          <Button type="link" style={buttonStyles} onClick={handleCta}>
            Need help?
          </Button>
        </ButtonWrapper>
      </FlowLayout>
      <CommonModal
        isModalOpen={openModal}
        hideButtons
        containerClassName='meeting-modal'
      >
        <ModalWrapper>
          <button type='button' onClick={() => setOpenModal(false)} aria-label="Close modal">
            <CloseIcon />
          </button>
          <iframe
            style={{
              width: '100%',
              height: '640px',
              border: 'none',
              margin: '0',
              padding: '0',
            }}
            title="hubspot"
            src={`https://info.uxcam.com/meetings/meet-uxcam/consultation?embed=true&email=${email}&firstname=${firstname}&lastname=${lastname}`}
          />
        </ModalWrapper>
      </CommonModal>
    </Wrapper>
  );
};

export default memo(ThankYou);