/* eslint-disable react/jsx-props-no-spreading */
import React, { memo, useState } from 'react';
import { useRouter } from 'next/router'


// context
import DashboardAccess from 'components/common/dashboardAccess';
import { FeatureFlagsProvider } from 'uxcam-frontend-components';
import { FormDataProvider, useFormData } from '../context/signupFlowData.context';
import { PageDataProvider, usePageState } from '../context/signupPages.context';

// components
import {
  EmailFlow,
  NameJobPhone,
  Source,
  TeamInvite,
  ThankYou,
  OrganizationApps,
} from '../FlowScreens';

const FeatureFlagParams = {
  applicationId: 'new-registration',
  anonymous: false, // override the default value of true
  key: 'anonymous-user', // prevent individual user tracking
}

const FlowScreenRender = (props) => {
  const router = useRouter()
  const referrer = router?.query?.referrer
  const { setValues } = useFormData()
  const { page, setPage } = usePageState();
  
  const { teamData } = props;

  React.useLayoutEffect( () => {
    if (teamData && page !== 5) {
      setPage(5)
      return
    }
    if (window.location.hash === '#verification' && page !== 4) {
      setPage(4)
    }
    if (page === null) {
      setPage(0)
    }
  }, [page, setPage, teamData])

  React.useEffect( () => {
    setValues( {
      referringPartnerVal: referrer
    } )
  }, [ referrer, setValues ] )

  // Hash management for tracking - updates URL hash based on current step
  React.useEffect(() => {
    if (typeof window === 'undefined' || page === null) return;

    const hashMap = {
      0: 'email',
      1: 'organization', 
      2: 'personal',
      3: 'source',
      4: 'verification'
    };

    const expectedHash = hashMap[page];
    if (expectedHash) {
      window.history.replaceState(null, null, `#${expectedHash}`);
    }
  }, [page]);

  switch (page) {
    case 0:
      return <EmailFlow { ...props } />
    case 1:
      return <OrganizationApps { ...props } />
    case 2:
      return <NameJobPhone {...props}/>;
    case 3:
      return <Source {...props}/>;
    case 4:
      return <ThankYou {...props}/>;
    case 5:
      return <TeamInvite {...props} />
    default:
      return null
  }
};

const SignUpFlow = (props) => {
  const { isActivation, message } = props;
    const [ featureFlagParams, setFeatureFlagParams ] = useState(FeatureFlagParams)

  React.useEffect( () => {
    try {
      const tryNewSignup = sessionStorage.getItem('tryNewSignup')
      if ( tryNewSignup ) {
        setFeatureFlagParams( ( prev ) => {
          return {
            ...prev,
            // @note: Vale requested to try the feature flag on prod, without enabling the feature flag
            tryNewSignup: true,
          }
        } )
      }
    } catch (err) {
      // silent fail
    }
  }, [] )

  return (
    <FeatureFlagsProvider
      user={ featureFlagParams }
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      clientKey={process.env.FEATURE_FLAG_ID}
    >
      <PageDataProvider>
        {isActivation ? (
          <DashboardAccess
            imgSrcLink={
              message
                ? '/static/icon-sad.svg'
                : '/static/icon-check-email.svg'
            }
            headerMsg={
              message
                ? 'Already Registered'
                : 'Thank you for signing up.'
            }
            reasonNoDashboardAccess={
              message ||
              'Please check your email to activate your account.' 
            }
            direct
          />) :
          <FormDataProvider>
            <FlowScreenRender {...props} />
          </FormDataProvider>
        }
      </PageDataProvider>
    </FeatureFlagsProvider>
  );
};

export default memo(SignUpFlow);
