import axios from 'axios'
import {axiosInstance} from './globalInstance'

const {CancelToken} = axios
let cancel = null
let screenCancel = null
let screenHeaderCancel = null
let screenEntryExitCancel = null
let request = 0

class ScreenApi {
  static async screenList (appId) {
    request++
    if (cancel) {
      await cancel(request)
    }
    const userRes = await axiosInstance.get(`${process.env.API_URL  }/app/${appId}/screen`, { withCredentials: true,
      cancelToken: new CancelToken((c) => {
            // An executor function receives a cancel function as a parameter
        cancel = c
        request = 0
      })
    })
    cancel = null
    return userRes
  }

  static async screenDetail (appId, cookies, screenname) {
    if (screenCancel) {
      await screenCancel(request)
    }
    const userRes = await axiosInstance.get(`${process.env.API_URL  }/app/${appId}/screen/${screenname}`, { withCredentials: true,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        screenCancel = c
        // request = 0;
      })
    })
    screenCancel = null
    return userRes
  }

  static async screenHeader (appId, cookies, screenname) {
    if (screenHeaderCancel) {
      await screenHeaderCancel(request)
    }
    const screenHeader = await axiosInstance.get(`${process.env.API_URL  }/app/${appId}/screen/${screenname}/show-header`, { withCredentials: true,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        screenHeaderCancel = c
        // request = 0;
      })
    })
    screenHeaderCancel = null
    return screenHeader
  }

  static async screenEntryExit (appId, cookies, screenname) {
    if (screenEntryExitCancel) {
      await screenEntryExitCancel(request)
    }
    const screenEntryExit = await axiosInstance.get(`${process.env.API_URL  }/app/${appId}/screen/${screenname}/show-entry-exit`, { withCredentials: true,
      cancelToken: new CancelToken((c) => {
        // An executor function receives a cancel function as a parameter
        screenEntryExitCancel = c
        // request = 0;
      })
    })
    screenEntryExitCancel = null
    return screenEntryExit
  }

  static async customScreenName (data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/screen/update-screens-name`,
      data,
      withCredentials: true,
      responseType: 'json',
      validateStatus (status) {
        return status >= 200 && status < 401
      }
    })
    return response
  }

  static async getScreenEditedList (appId) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/screen/display-screens-list`,
      data: {appid: appId},
      withCredentials: true
    })
    return response;
  }
}

export default ScreenApi
