import React from "react"
import styled from "styled-components"
import { showIntercom } from "Utils/constants"

const ContactText = styled.p`
	font-size: 14px !important;
	line-height: 22px !important;
	color: #49576e !important;
	text-align: left;
	margin-bottom: 0 !important;
	button {
		color: #5d97ff;
		border : none;
		background-color: transparent;
		cursor: pointer;
		padding: 0;
		margin: 0;
		padding-left: 5px;
	}
`;

interface IProps {
	teamData?: unknown
}

const JoinExistingOrganization = ({ teamData }: IProps) => {

	if (teamData) {
		return (
			<>
				<br />
				<br />
			</>
		)
	}

	return (
		<ContactText data-intercom-target="contact-us">
			Joining an existing organization?
			<button
				type="button"
				id="itc-contact-us"
				onClick={() => showIntercom()}
				data-intercom-target="contact-us-btn"
			>
				Contact Us
			</button>
		</ContactText>
	)
}

export default JoinExistingOrganization